package android.app; import android.content.Intent; public class Activity {public boolean finishing,destroyed,focus=true;public int fine=0,coarse=0,starts; public boolean isFinishing(){return finishing;}public boolean isDestroyed(){return destroyed;}public boolean hasWindowFocus(){return focus;}public int checkSelfPermission(String p){return p.equals("fine")?fine:coarse;}public void startForegroundService(Intent i){starts++;}}
